-- Names and periodicities from the UNIVC v3 indicator matrix. Formulas/sources can be enriched progressively.
on conflict(code) do update set name=excluded.name,periodicity=excluded.periodicity,directorate_code=excluded.directorate_code;

select code,
  case when periodicity ilike '%semestral%' then 'semester' when periodicity ilike '%trimestral%' then 'quarter' when periodicity ilike '%bimestral%' then 'bimonth' else 'month' end,
  5,1
from public.indicator_definitions
on conflict(indicator_code) do nothing;
